SELECT p.gender, EXTRACT(YEAR FROM p.dob) AS age, d.icd_code, d.icd_version, COUNT(*) AS procedure_count, SUM(CASE WHEN (a.dischtime - a.admittime) BETWEEN 1 AND 4 THEN 1 ELSE 0 END) AS procedures_within_first_four_days, SUM(CASE WHEN (a.dischtime - a.admittime) BETWEEN 5 AND 8 THEN 1 ELSE 0 END) AS procedures_within_next_four_days, SUM(CASE WHEN d.primary_care_provider_id IS NOT NULL THEN 1 ELSE 0 END) AS procedures_with_primary_care_provider, SUM(CASE WHEN d.secondary_care_provider_id IS NOT NULL THEN 1 ELSE 0 END) AS procedures_with_secondary_care_provider FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM p.dob) = 57 AND d.icd_code = 'A01.0' AND d.icd_version = '4' GROUP BY p.gender, age, d.icd_code, d.icd_version ORDER BY p.gender, age, d.icd_code, d.icd_version NULLS LAST;